internal object DuaAmDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("ሱቡሁን ቁዱስ (ሩኩ እና ሱጁድ)", "(አላህ) የጠራ፣ የተቀደሰ፣ የመላእክትና የመንፈስ ጌታ (ጅብሪል) ነው።", "በሩኩና በሱጁድ።", "ነብዩ ﷺ ይህንን በሩኩ እና በሱጁድ አንብበውታል።"),
        "dua_sujood_dhanbi_kullah" to DuaText("በሱጁድ፡ ኃጢአቴን ሁሉ ይቅር በል።", "አላህ ሆይ ወንጀሎቼን ሁሉ ይቅር በለኝ - ትንሹም ትልቁም፣ ፊተኛውና መጨረሻው፣ ክፍት እና ስውር።", "በሱጁድ.", "ስግደት ዱዓዎች የሚመለሱበት ቦታ ነው።"),
        "dua_sujood_ridaka" to DuaText("በአንተ ደስታ ውስጥ መጠጊያ", "አላህ ሆይ በውዴታህ ከቁጣህ፣ ከቅጣትህም በምህረትህ እጠበቃለሁ፣ ከአንተም እጠበቃለሁ። ሙሉ በሙሉ አንተን ማመስገን አልችልም; አንተ እራስህን እንዳመሰገንክ ነህ።", "በሱጁድ - አኢሻ (RA) ነቢዩ ﷺ እንዲህ ሲሉ ሰማች።", "የነቢዩ ሱጁድ ዱአ ﷺ።"),
        "dua_tashahhud" to DuaText("ተሻሁድ (አት-ታሂያት)", "ሁሉም የቃል፣ አካላዊ እና የገንዘብ አምልኮዎች ለአላህ ናቸው። ሰላም በአንተ ላይ ይሁን ነብዩ የአላህ እዝነት እና በረከቶቹ። ሰላም በኛ እና በአላህ ጻድቃን ባሮች ላይ ይሁን። ሊመለክ የሚገባው አላህ ብቻ እንደሆነ እመሰክራለው ሙሐመድ ﷺ የሱ አገልጋይና መልእክተኛ መሆናቸውን እመሰክራለሁ።", "በእያንዳንዱ መቀመጫ - አብደላህ ኢብኑ መስዑድ (RA) (የሐነፊ ልማድ) ዘግበውታል።", "ነቢዩ ﷺ እንደ ቁርኣን ሱራ አስተማሩት።"),
        "dua_sajdah_tilawah" to DuaText("የንባብ ሰጃዳህ", "ፊቴ ለፈጠረው ሰግዶ በመስማትና ማየትን በኃይሉና በኃይሉ ላወጣው።", "በንባብ ሱጁድ ውስጥ።", "ነብዩ ﷺ በሌሊት ስግደት ላይ እንዲህ አሉ።"),
        "dua_after_witr" to DuaText("ከዊትር በኋላ", "ክብር ንጉሠ ቅዱሳን ይሁን።", "ሶስት ጊዜ ከዊትር ሰላም በኋላ, ለሶስተኛ ጊዜ ድምጽን ከፍ በማድረግ.", "ነቢዩ ﷺ ከዊትር በኋላ እንዲህ ብለው ነበር።"),
        "dua_tahajjud_nur" to DuaText("ታሃጁድ የመክፈቻ ልመና", "አላህ ሆይ ምስጋና ላንተ ይገባው። አንተ የሰማያት፣ የምድርና የውስጣቸውም ሁሉ ረዳቶች ነህ። ምስጋና ላንተ ነው። አንተ የሰማይ፣ የምድርና በውስጣቸው ያለው ሁሉ ብርሃን ነህ። ምስጋና ላንተ ነው። እውነት አንተ ነህ ቃል ኪዳንህ እውነት ነው ካንተ ጋር መገናኘት እውነት ነው ቃልህ እውነት ነው ጀነት እውነት ነው ጀሀነም እውነት ነብያቶች ሙሀመድ ﷺ እውነት ነው ሰዓቲቱም እውነት ነው", "የሌሊት ሶላት (ተሀጁድ) ሲጀመር (የዱዓ መክፈቻ ክፍል)።", "ነብዩ ﷺ ለታሀጁድ መነሳት ላይ ይህን አነበቡት (ሙሉ ዱዓ በአል-ቡካሪ ውስጥ ነው)።"),
        "dua_rabba_jibrail" to DuaText("በተከራካሪ ጉዳዮች ምራኝ።", "የጅብሪል፣ ሚካኢልና ኢስራፊል ጌታ የሆንህ ሰማያትንና ምድርን የፈጠርክ ሩቁንና ሩቁንም ዐዋቂ የሆንህ አላህ ሆይ! በባሮችህ መካከል ይለያዩበት በነበሩት ነገር ትፈርዳለህ። በአንተ ፍቃድ ምራኝ። አንተ የምትሻውን ሰው ወደ ቀጥተኛው መንገድ ትመራለህ።", "በታሃጁድ መጀመሪያ ላይ - በአለመግባባት ውስጥ ወደ እውነት ለመምራት.", "ነቢዩ ﷺ የሌሊት ሶላታቸውን በዚህ ዱዓ ጀመሩ።"),
        "dua_going_to_mosque_nur" to DuaText("ወደ መስጂድ መሄድ (የብርሃን ዱዓ)", "አሏህ ሆይ ብርሀንን በልቤ፣በአይኖቼ ብርሃን፣በጆሮዬ ብርሃንን፣በቀኜ ብርሃንን፣በግራዬ ላይ ብርሃንን፣ብርሃንን ከእኔ በላይ፣ብርሃንን ከእኔ በታች፣ብርሃንን ከፊት ለፊቴ፣ከኋላዬ ብርሃን አድርግልኝ።", "ለፈጅር ወደ መስጂድ ሲሄዱ።", "ነቢዩ ﷺ ለጸሎት ሲወጡ ይህን አንብበው ነበር።"),
        "dua_waswasa_salah" to DuaText("ዋስዋሳ በሳላህ ወቅት (ኪንዛብ)", "ከተረገመው ሸይጣን በአላህ እጠበቃለሁ።", "በጸሎት ጊዜ ሰይጣናዊ ሹክሹክታ ሲመጣ ጥገኝነት ፈልጉ እና በቀላሉ ወደ ግራ ሶስት ጊዜ ይትፉ።", "ዑስማን ኢብኑ አቢል-አስ (RA) ይህን አደረገ እና ሹክሹክታዎቹ ሄዱ።"),
        "dua_alimal_ghayb" to DuaText("ሩቁን ነገር ዐዋቂ ነው።", "የሩቅና የሚታየውን ዐዋቂ የሰማያትና የምድር ፈጣሪ የሁሉም ነገር ጌታ የሆንህ አላህ ሆይ! ከአንተ በቀር ሌላ አምላክ እንደሌለ እመሰክራለሁ። እኔ ከራሴ ክፋት፣ ከሰይጣንና ከሽርክም ክፋት በአንተ እጠበቃለሁ።", "ጥዋት፣ ማታ እና ከመተኛቱ በፊት - ነቢዩ ﷺ አቡበክርን (RA) አስተምረውታል።", "ከራስ እና ከሰይጣን ክፋት መከላከል።"),
        "dua_fitratil_islam" to DuaText("በእስልምና ፊታው ላይ", "በእስልምና ፊታውራ ላይ፣ በቅንነት ቃል፣ በነብያችን ሙሐመድ ﷺ እና በአባታችን ኢብራሂም (AS) መንገድ ላይ፣ ቀና እና ሙስሊም ከነበሩት፣ ከሙሽሪኮች ባልነበረው መንገድ ላይ ገብተናል።", "ጠዋት ላይ.", "በየማለዳው እምነትን ማደስ።"),
        "dua_amsayna_fitrah" to DuaText("በእስልምና ፊታው ላይ ምሽት", "በእስልምና ፊታውራ፣ በቅንነት ቃል፣ በነብያችን ሙሐመድ ﷺ እና በአባታችን ኢብራሂም (AS) መንገድ ላይ፣ ቀና እና ሙስሊም ከነበሩት፣ ከሙሽሪኮች ባልነበረው መንገድ ላይ ማምሻውን ደርሰናል።", "ምሽት ላይ.", "በየምሽቱ እምነትን ማደስ።"),
        "dua_tahleel_10_fajr" to DuaText("ከፈጅር እና ከመግሪብ በኋላ አስር ተህሊል።", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናም የርሱ ብቻ ነው። ምስጋናም የርሱ ብቻ ነው። ሕያው ያደርጋል ይገድላልም። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው።", "ከፈጅር (እና ከመግሪብ) በኋላ አስር ጊዜ ከመቀመጫህ ወይም ከመናገርህ በፊት።", "አሥር መልካም ሥራዎች፣ አሥር ኃጢአቶች ተሰርዘዋል፣ አሥር ደረጃዎች ከፍ ከፍ ያሉ እና ቀኑን ሙሉ ከሰይጣን ይጠበቁ።"),
        "dua_la_hawla_kanz" to DuaText("የጀነት ውድ ሀብት", "ከአላህ ጋር ካልሆነ በስተቀር ምንም ሃይል እና ሃይል የለም።", "ብዙውን ጊዜ, በማንኛውም ጊዜ.", "ከጀነት ሀብቶች አንዱ ነው።"),
        "dua_four_beloved_words" to DuaText("አራቱ በጣም የተወደዱ ቃላት", "ክብር ለአላህ ይገባው፡ ምስጋና ሁሉ ለአላህ ነው፡ ሊመለክ የሚገባው አላህ ብቻ ነው፡ አላህም ታላቁ ነው።", "አላህ ዘንድ በጣም የተወደዱ ቃላት።", "ፀሐይ ከምትወጣበት ነገር ሁሉ ይልቅ ለነቢዩ ﷺ የተወደዱ ናቸው።"),
        "dua_two_light_words" to DuaText("ሁለት ቃላት በምላስ ላይ ብርሃን", "ምስጋና ለአላህ ይገባው። ክብር ለታላቁ አላህ ይሁን።", "በምላሱ ላይ ብርሃን ፣ በመለኪያው ላይ ከባድ።", "እጅግ በጣም ርህሩህ የተወደድክ ምላስ የቀለለ በመለኪያም ላይ የከበደ ነው። (የቡኻሪ የመጨረሻ ሀዲስ)"),
        "dua_ya_dhal_jalal" to DuaText("ያ ዳል-ጀላሊ ወል-ኢክራም።", "የክብርና የክብር ባለቤት ሆይ!", "በዱዓ ያዙት - የነቢዩ ﷺ መመሪያ።", "ነቢዩ ﷺ “ያ ዳል-ጀላሊ ወል-ኢክራም” ያዙ።"),
        "dua_sleep_wadatu_janbi" to DuaText("በአንተ ስም አኖራለሁ", "በስምህ ጌታዬ ጎኔን አኖራለሁ በስምህም እነሳለሁ። ነፍሴን ከወሰድክ እዘንላት፣ ከለቀቅካትም ጻድቃን ባሮችህን እንደምትጠብቅ ጠብቀው።", "አልጋውን አቧራ ካጸዳ በኋላ እና ከተኛ በኋላ.", "ከመተኛቱ በፊት ነፍስን ለአላህ አደራ መስጠት።"),
        "dua_sleep_khalaqta_nafsi" to DuaText("ነፍሴን ፈጠርከው", "አላህ ሆይ አንተ ነፍሴን ፈጠርክ አንተም ትወስዳለህ። ሞቷም ሕይወቷም የአንተ ነው። በሕይወት ብታቆየው ጠብቀው፤ ብታስገድለውም ይቅር በለው። አላህ ሆይ ጤናን እጠይቅሃለሁ።", "ከመተኛቱ በፊት - ኢብኑ ዑመር (RA) ዘግበውታል።", "ነብዩ ﷺ በመኝታ ሰአት እንዲህ ሲሉ አዘዙ።"),
        "dua_sleep_atamana" to DuaText("ከመተኛቱ በፊት ምስጋና", "ምስጋና ሁሉ ለአላህ የተገባው፣ ላበላን፣ ላጠጣን፣ ለበቃን እና መጠለያ ላደረገን። የሚጠግባቸው ወይም የሚጠለሉላቸው ስንቶች ናቸው።", "ወደ መኝታ ሲሄዱ.", "ነቢዩ ﷺ ወደ መኝታ ሲሄዱ እንዲህ ብለዋል."),
        "dua_sleep_rabbas_samawat" to DuaText("የሰማያት ጌታ - ዕዳችንን ክፈል", "O Allah, Lord of the heavens, the earth and the Mighty Throne, our Lord and Lord of all things, Splitter of the seed and the date-stone, Revealer of the Torah, the Injil and the Furqan! ጓዳውን ከያዝክበት ነገር ሁሉ ከክፉ በአንተ እጠበቃለሁ። አላህ ሆይ አንተ አንደኛ ነህ ከአንተ በፊት ምንም የለም; አንተ የመጨረሻ ነህ ከአንተ በኋላ ምንም የለም; አንተ ገላጭ ነህ ከአንተ በላይ ምንም የለም; አንተ ስውር ነህ ከአንተ የተደበቀ ነገር የለም። እዳችንን አስተካክለን ከድህነት ነፃ አውጣን።", "ከመተኛቱ በፊት, በቀኝ በኩል መተኛት - ለፋጢማ (RA) ተምሯል.", "ከእዳ እና ከችግር ለመገላገል ዱዓ።"),
        "dua_sleep_fear" to DuaText("በእንቅልፍ ውስጥ ፍርሃት ወይም አለመረጋጋት", "ከቁጣውና ከቅጣቱ፣ ከባሮቹ ክፋት፣ ከሰይጣናት ሹክሹክታና ወደ እኔ ከመምጣታቸው ፍጹም በሆነው የአላህ ቃል እጠበቃለሁ።", "በእንቅልፍ ውስጥ ፍርሃት ወይም ጭንቀት ሲሰማዎት.", "እንዲህ ማድረጉ አይጎዳውም."),
        "dua_waking_afani" to DuaText("መንቃት፡ ነፍሴን መለሰላት", "ምስጋና ሁሉ ለአካሌ ደኅንነትን ለሰጠ፣ ነፍሴን ወደኔ የመለሰልኝና እንዳስታውስ ለፈቀደልኝ አላህ ይገባው።", "በመንቃት ላይ።", "ለአዲስ ጥዋት ምስጋና።"),
        "dua_allahu_rabbi" to DuaText("አላህ ሆይ አላህ የኔ ጌታ ነው።", "አላህ ሆይ፣ አላህ ጌታዬ ነው። በርሱ ምንም አላጋራም።", "በሀዘን ወይም በጭንቀት - ነብዩ ﷺ አስማ ቢንት ኡማይስ (RA) አስተማሩት።", "በችግር ጊዜ ተውሂድን መያዝ።"),
        "dua_rahmataka_arju" to DuaText("ምህረትህን ተስፋ አደርጋለሁ", "አላህ ሆይ ተስፋ የማደርገው የአንተን እዝነት ነውና ለዓይን ጥቅሻ እንኳን ለራሴ አትተወኝ ጉዳዮቼንም አስተካክል። ከአንተ በቀር አምላክ የለም።", "በጭንቀት ውስጥ ያለ ሰው ዱዓ (ዳአዋት አል-መክሩብ)።", "ነቢዩ ﷺ በጭንቀት ውስጥ ያለ ሰው ዱዓ ብለው ጠሩት።"),
        "dua_against_enemy_ahzab" to DuaText("በጠላት ጦር ላይ", "የመፅሀፍ ባለቤት የሆንክ አላህ ሆይ ለሒሳቡ ፈጣን! ኮንፈደሬቶችን አሸንፉ። አላህ ሆይ አሸንፋቸውና አንቀጥቅጣቸው።", "በጠላት ላይ - የ Confederates ጦርነት ዱዓ.", "የነቢዩ ﷺ ዱዓ በጠላት ላይ።"),
        "dua_anta_adudi" to DuaText("አንተ የእኔ ድጋፍ ነህ", "አላህ ሆይ አንተ ረዳቴና ረዳቴ ነህ። በአንተ አቅጃለሁ፣ በአንተ እቀድማለሁ፣ በአንተም እታገላለሁ።", "ከውድድር በፊት ወይም ትልቅ ፈተና።", "ነቢዩ ﷺ በጦርነት እንዲህ ብለው ነበር።"),
        "dua_ikfinihim" to DuaText("በነሱ ላይ ይብቃኝ።", "አላህ ሆይ የፈለግከውን በቃኝ በነሱ ላይ።", "በጨቋኞች ክፋት ላይ - በዲች ህዝቦች ታሪክ ውስጥ የልጁ ዱዓ.", "አላህ ልጁን ከጨቋኞች አዳነው።"),
        "dua_qadarullah" to DuaText("አንድ መጥፎ ነገር ሲከሰት", "የአላህ ውሳኔ ነው፤ የሚሻውንም አደረገ።", "አንድ ደስ የማይል ነገር ሲከሰት 'ቢሆን' ከማለት ይልቅ።", "ለሸይጣን በሩን ከፈተለት።"),
        "dua_ala_kulli_hal" to DuaText("ውዳሴ በሁሉም ሁኔታ", "በሁሉም ሁኔታዎች ውስጥ ምስጋና ሁሉ ለአላህ ይሁን።", "ያልተወደደ ነገር ሲከሰት።", "ነቢዩ ﷺ የማይወደውን ነገር ሲጋፈጡ እንዲህ ብለው ነበር።"),
        "dua_dogs_barking" to DuaText("የሚሰሙ ውሾች በምሽት ይጮሀሉ።", "ከተረገመው ሸይጣን በአላህ እጠበቃለሁ።", "በሌሊት ውሾች ሲጮሁ ወይም የአህያ ጩኸት ሲሰሙ።", "የማታዩትን ያያሉ።"),
        "dua_leaving_home_adilla" to DuaText("ከመሳሳት መሸሸጊያ", "አሏህ ሆይ እኔ እንዳላሳሳት ወይም እንዳልመራኝ፣ እንዳላንሸራተት ወይም እንዳላንሸራተት፣ እንዳልበደል ወይም እንዳልበደል፣ ስንፍና እንዳላደርግ በአንተ እጠበቃለሁ።", "ከቤት ሲወጡ - በኡሙ ሰላማ (RA) ዘግበውታል።", "ነብዩ ﷺ ይህንን ያነቡት ከቤታቸው በወጡ ቁጥር ነው።"),
        "dua_ascending_descending" to DuaText("መውረድ እና መውረድ", "አላህ (በሚወጣበት ጊዜ) ታላቁ ነው። - ክብር ለአላህ ይገባው (በወረደ ጊዜ)።", "በጉዞ ላይ ወደ ላይ ስትወጣ 'አላሁ አክበር' ስትወርድ ደግሞ 'ሱብሀን አላህ' በል።", "በጉዞ ላይ እያሉ የሰሃባዎች ልምምድ (RA)።"),
        "dua_traveller_sahar" to DuaText("የመንገደኛ ዱዓ ከማለዳ በፊት", "ሰሚ የአላህን ውዳሴና በላያችን ያለውን መልካም ውለታ ሰምቶ (አስተላልፏል)። ጌታችን ሆይ አጅበን ውለታህንም ለኛ አድርግልን - (ይህን እላለሁ) በአላህ ከእሳት ተጠበቅ።", "በጉዞ ላይ፣ ጎህ ሳይቀድ።", "ነቢዩ ﷺ ሲጓዙ ገና ጎህ ሳይቀድ ተናግሯል።"),
        "dua_zawwadakallah" to DuaText("ለተጓዥ፡- አላህ ተቅዋ ይስጠን", "አላህ ለጉዞህ ተቅዋ ይስጥህ ወንጀሎችህን ይማርልህ የትም ብትሆን መልካም ነገር ያድርግልህ።", "መንገደኛ ስንብት ሲጫረት።", "ነቢዩ ﷺ ይህንን ዱዓ ለጉዞ ለወጣ ሰው ሰጡ።"),
        "dua_traveller_to_resident" to DuaText("ከኋላ ለሚቆዩት ተጓዥ", "አደራ ለአላህ አደራ እላችኋለሁ።", "ቤተሰቡን ሲሰናበት በተጓዡ የተናገረው።", "የቤተሰብን ደህንነት ለአላህ አደራ መስጠት።"),
        "dua_entering_village" to DuaText("ከተማ ወይም መንደር መግባት", "የሰባቱ ሰማያትና የጥላቻቸው ሁሉ ጌታ፣ የሰባት ምድርና የተሸከሙት ሁሉ ጌታ፣ የሰይጣናት እና የሚጠምሙ ሁሉ ጌታ፣ የነፋሶችና የሚበተኑት ሁሉ ጌታ የሆንህ አላህ ሆይ! የዚችን ከተማ መልካም ነገርና የሕዝቦቿን መልካም ነገር እንለምንሃለን ከክፉዋ፣ ከህዝቦቿ ክፋትና በውስጧ ካለው መጥፎ ነገር በአንተ እንጠበቃለን።", "ከተማ ወይም ከተማ ከመግባትዎ በፊት.", "ነብዩ ﷺ ከተማ መግባት በፈለጉ ጊዜ ይህንን ያነብ ነበር።"),
        "dua_vehicle_stumbles" to DuaText("ተሽከርካሪው ሲደናቀፍ", "በአላህ ስም።", "ተራራው ወይም ተሽከርካሪው ሲንሸራተት ወይም ሲደናቀፍ 'ሰይጣን ይጥፋ' ከማለት ይልቅ።", "ቢስሚላህ ማለት ሸይጣንን ወደ ዝንብ መጠን እንዲቀንስ ያደርገዋል።"),
        "dua_ajz_kasal_haram" to DuaText("ከደካማነት እና ከእድሜ መሸሽ", "አላህ ሆይ ከድክመትና ከስንፍና፣ ከፈሪነትና ከእርጅና፣ ከህይወትና ከሞት ፈተና፣ ከቀብር ቅጣት በአንተ እጠበቃለሁ።", "ሁሉን አቀፍ የጥገኝነት ዱዓ።", "ነብዩ ﷺ ብዙ ጊዜ ያደረጉት ዱአ።"),
    )
}
